- name: Try Roo (Orchestrator mode) — primary coder lane
  id: roo
  if: env.ROO_API_KEY != ''
  continue-on-error: true
  env:
    ROO_API_KEY: ${{ secrets.ROO_API_KEY }}
    ROO_MODE: ${{ vars.ROO_MODE || 'orchestrator' }}
    ROO_RUN_COMMAND: ${{ vars.ROO_RUN_COMMAND }}
    GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
    ISSUE_NUMBER: ${{ steps.issue.outputs.issue_number }}
    ISSUE_TITLE: ${{ steps.issue.outputs.issue_title }}
    ISSUE_BODY: ${{ steps.issue.outputs.issue_body }}
  run: |
    set -euo pipefail
    # Roo writes its result to the same JSON shape OpenRouter expects:
    # { "commit_message": "...", "files_written": [ "<path>", ... ] }
    # If the public Roo surface differs from the default below, set the
    # ROO_RUN_COMMAND repo variable to a one-liner that produces the
    # same /tmp/openrouter-coder-result.json. The fallback OpenRouter
    # step runs unchanged if Roo soft-fails or returns zero files.
    if [[ -n "${ROO_RUN_COMMAND:-}" ]]; then
      eval "$ROO_RUN_COMMAND"
    else
      npx --yes @roocode/cli run \
        --mode "$ROO_MODE" \
        --task "$ISSUE_TITLE"$'\n\n'"$ISSUE_BODY" \
        --repo "$PWD" \
        --output-json /tmp/openrouter-coder-result.json
    fi
    if [[ -s /tmp/openrouter-coder-result.json ]]; then
      files=$(python3 -c "import json,sys; d=json.load(open('/tmp/openrouter-coder-result.json')); print(len(d.get('files_written') or []))")
    else
      files=0
    fi
    echo "files_written=$files" >> "$GITHUB_OUTPUT"
- name: Generate code changes with OpenRouter (fallback)
  id: coder
  if: steps.roo.outcome != 'success' || steps.roo.outputs.files_written == '0' || steps.roo.outputs.files_written == ''
  env:
    OPENROUTER_API_KEY: ${{ secrets.OPENROUTER_API_KEY }}
    GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
    GITHUB_REPOSITORY: ${{ github.repository }}
    ISSUE_NUMBER: ${{ steps.issue.outputs.issue_number }}
    ISSUE_TITLE: ${{ steps.issue.outputs.issue_title }}
    ISSUE_BODY: ${{ steps.issue.outputs.issue_body }}
    WR_MODEL: ${{ vars.WR_MODEL || 'anthropic/claude-opus-4.7' }}
  run: |
    python .github/scripts/openrouter_coder.py --output-path /tmp/openrouter-coder-result.json

