12	  cancel-in-progress: true
13	permissions:
14	  contents: read
15	  pull-requests: write
16	  issues: write
17	  checks: read
18	jobs:
19	  promote-draft:
20	    name: Promote Draft PR When CI Passes
21	    runs-on: ubuntu-latest
22	    if: |
23	      github.event.pull_request.head.repo.full_name == github.repository &&
24	      github.event.pull_request.draft == true &&
25	      (github.event.action == 'synchronize' || github.event.action == 'reopened')
26	    steps:
27	      - name: Check all CI status checks for this commit
28	        id: check-status
29	        uses: actions/github-script@v9.0.0
30	        with:
31	          github-token: ${{ github.token }}
32	          script: |
33	            // Job names that belong to this workflow — exclude them from the
34	            // external-check evaluation so we never block on ourselves.
35	            const SELF_JOB_NAMES = new Set([
36	              'Promote Draft PR When CI Passes',
37	              'Label Linked Issues as In-Review',
38	              'Remove In-Review Label on PR Close',
39	            ]);
40	            const ALLOWED_CONCLUSIONS = new Set(['success', 'skipped', 'neutral']);
41	
42	            // Poll until all external checks complete or we time out.
43	            const INITIAL_WAIT_MS  = 15_000;   // 15 s — let checks register first
44	            const POLL_INTERVAL_MS = 30_000;   // re-check every 30 s
45	            const MAX_WAIT_MS      = 8 * 60 * 1000; // 8 minutes — give up after this
46	
47	            await new Promise(r => setTimeout(r, INITIAL_WAIT_MS));
48	
49	            let elapsed = INITIAL_WAIT_MS;
50	
51	            while (true) {
52	              const { data } = await github.rest.checks.listForRef({
53	                owner: context.repo.owner,
54	                repo: context.repo.repo,
55	                ref: context.payload.pull_request.head.sha,
56	                per_page: 100,
57	              });
58	
59	              const runs = data.check_runs.filter(r => !SELF_JOB_NAMES.has(r.name));
60	              core.info(`[${elapsed / 1000}s] Found ${runs.length} external check run(s):`);
61	              runs.forEach(r => core.info(`  • ${r.name}: ${r.status} / ${r.conclusion}`));
62	
63	              if (runs.length === 0) {
64	                // No external CI configured — safe to promote immediately.
65	                core.info('No external check runs found — auto-promoting.');
66	                core.setOutput('all_passed', 'true');
67	                return true;
68	              }
69	
70	              const allDone = runs.every(r => r.status === 'completed');
71	
72	              if (allDone) {
73	                const allPassed = runs.every(r => ALLOWED_CONCLUSIONS.has(r.conclusion));
74	                if (!allPassed) {
75	                  const failed = runs.filter(r => !ALLOWED_CONCLUSIONS.has(r.conclusion));
76	                  failed.forEach(r => core.warning(`  ✗ ${r.name}: ${r.conclusion}`));
77	                }
78	                core.setOutput('all_passed', allPassed ? 'true' : 'false');
79	                return allPassed;
80	              }
81	
82	              if (elapsed >= MAX_WAIT_MS) {
83	                const pending = runs.filter(r => r.status !== 'completed');
84	                core.warning(`Timed out after ${MAX_WAIT_MS / 1000}s. Still pending:`);
85	                pending.forEach(r => core.warning(`  • ${r.name}`));
86	                core.setOutput('all_passed', 'false');
87	                return false;
88	              }
89	
90	              const pendingCount = runs.filter(r => r.status !== 'completed').length;
91	              core.info(`Waiting for ${pendingCount} check(s) to finish... (${elapsed / 1000}s elapsed)`);
92	              await new Promise(r => setTimeout(r, POLL_INTERVAL_MS));
93	              elapsed += POLL_INTERVAL_MS;
94	            }
95	      - name: Convert draft PR to Ready for Review
96	        if: steps.check-status.outputs.all_passed == 'true'
97	        uses: actions/github-script@v9.0.0
98	        with:
99	          github-token: ${{ secrets.READY_FOR_REVIEW_TOKEN != '' && secrets.READY_FOR_REVIEW_TOKEN || secrets.ADMIN_GITHUB_TOKEN != '' && secrets.ADMIN_GITHUB_TOKEN || github.token }}
100	          script: |
101	            await github.graphql(`
102	              mutation($prId: ID!) {
103	                markPullRequestReadyForReview(input: { pullRequestId: $prId }) {
104	                  pullRequest { number title isDraft }
105	                }
106	              }
107	            `, { prId: context.payload.pull_request.node_id });
108	
109	            core.notice(
110	              `✅ PR #${context.payload.pull_request.number} — all CI checks passed. ` +
111	              `Promoted from Draft to Ready for Review.`
112	            );
113	    timeout-minutes: 30
114	  label-linked-issues:
115	    name: Label Linked Issues as In-Review
116	    runs-on: ubuntu-latest
117	    if: |
118	      github.event.pull_request.head.repo.full_name == github.repository &&
119	      (
120	        github.event.action == 'ready_for_review' ||
121	        (github.event.action == 'opened' && github.event.pull_request.draft == false)
122	      )
123	    steps:
124	      - name: Ensure `in-review` label exists
125	        uses: actions/github-script@v9.0.0
126	        with:
127	          github-token: ${{ github.token }}
128	          script: |
129	            try {
130	              await github.rest.issues.getLabel({
131	                owner: context.repo.owner,
132	                repo: context.repo.repo,
133	                name: 'in-review',
134	              });
135	            } catch (e) {
136	              if (e.status === 404) {
137	                try {
138	                  await github.rest.issues.createLabel({
139	                    owner: context.repo.owner,
140	                    repo: context.repo.repo,
141	                    name: 'in-review',
142	                    color: 'fbca04',
143	                    description: 'Linked PR is open and ready for review',
144	                  });
145	                  core.info('Created label: in-review');
146	                } catch (ce) {
147	                  core.warning(`Failed to create label: ${ce.message}`);
148	                }
149	              } else {
150	                core.warning(`Failed to get label: ${e.message}`);
151	              }
152	            }
153	      - name: Find linked issues and apply `in-review` label
154	        id: find-issues
155	        uses: actions/github-script@v9.0.0
156	        with:
157	          github-token: ${{ github.token }}
158	          script: |
159	            const body  = context.payload.pull_request.body  || '';
160	            const title = context.payload.pull_request.title || '';
161	            const text  = `${title}\n${body}`;
162	
163	            // ── 1. Match closing keywords in PR title / body ─────────────────
164	            // Match: Closes #N, Fixes #N, Resolves #N (all common variants)
165	            const pattern = /(?:close[sd]?|fix(?:es|ed)?|resolve[sd]?)\s+#(\d+)/gi;
166	            const matches = [...text.matchAll(pattern)];
167	            const issueNumberSet = new Set(matches.map(m => parseInt(m[1])));
168	
169	            // ── 2. Parse branch name for issue/<N>- pattern ───────────────────
170	            // Covers branches created by the create-issue-branch action using
171	            // the label-based prefixes defined in .github/issue-branch.yml:
172	            //   issue/69-i-need-the-issue-to-close-...   (fallback prefix)
173	            //   feature/69-some-title                    (enhancement)
174	            //   bugfix/69-some-title                     (bug)
175	            //   docs/69-some-title                       (documentation)
176	            //   hotfix/69-some-title                     (security)

