1	#!/usr/bin/env node
2	"use strict";
3	
4	/**
5	 * Unit tests for openrouter-personas.js
6	 *
7	 * Covers persona registry shape, handle/mode resolution, message construction,
8	 * and instantiation lifecycle (eager vs on-assignment). Does not make live API
9	 * calls; runs that would hit OpenRouter are asserted to reject with a fake key.
10	 */
11	
12	const {
13	  PERSONA_REGISTRY,
14	  INSTANTIATION_MODES,
15	  getPersonas,
16	  getPersona,
17	  normalizeMode,
18	  buildMessages,
19	  instantiate,
20	  instantiateFleet,
21	} = require("../scripts/openrouter-personas");
22	
23	let testsPassed = 0;
24	let testsFailed = 0;
25	
26	function assertEqual(actual, expected, testName) {
27	  if (JSON.stringify(actual) === JSON.stringify(expected)) {
28	    console.log(`✅ ${testName}`);
29	    testsPassed++;
30	  } else {
31	    console.error(`❌ ${testName}`);
32	    console.error(`  Expected: ${JSON.stringify(expected)}`);
33	    console.error(`  Actual: ${JSON.stringify(actual)}`);
34	    testsFailed++;
35	  }
36	}
37	
38	function assertTrue(condition, testName) {
39	  if (condition) {
40	    console.log(`✅ ${testName}`);
41	    testsPassed++;
42	  } else {
43	    console.error(`❌ ${testName}`);
44	    testsFailed++;
45	  }
46	}
47	
48	function assertThrows(fn, testName) {
49	  try {
50	    fn();
51	    console.error(`❌ ${testName} - Expected to throw but didn't`);
52	    testsFailed++;
53	  } catch (err) {
54	    console.log(`✅ ${testName}`);
55	    testsPassed++;
56	  }
57	}
58	
59	async function assertRejects(promise, testName) {
60	  try {
61	    await promise;
62	    console.error(`❌ ${testName} - Expected to reject but didn't`);
63	    testsFailed++;
64	  } catch (err) {
65	    console.log(`✅ ${testName}`);
66	    testsPassed++;
67	  }
68	}
69	
70	async function runTests() {
71	  console.log("Running openrouter-personas.js tests...\n");
72	
73	  // Registry shape
74	  console.log("Test Group: Persona Registry");
75	  assertEqual(
76	    Object.keys(getPersonas()).sort(),
77	    ["mindmappr", "oaudrey", "openrouter", "professor"],
78	    "Should register exactly the four named personas"
79	  );
80	  assertTrue(
81	    Object.values(PERSONA_REGISTRY).every(
82	      (p) => p.handle && p.name && p.role && p.instructions && (p.profile || p.models)
83	    ),
84	    "Every persona has handle, name, role, instructions, and a routing strategy"
85	  );
86	  assertTrue(
87	    Array.isArray(PERSONA_REGISTRY.professor.models) &&
88	      PERSONA_REGISTRY.professor.models[0] === "perplexity/sonar-pro",
89	    "The Professor pins the Perplexity Sonar model lane"
90	  );
91	
92	  // Handle resolution
93	  console.log("\nTest Group: getPersona");
94	  assertEqual(getPersona("oaudrey").name, "oAudrey", "Resolves a plain handle");
95	  assertEqual(getPersona("@oAudrey").name, "oAudrey", "Resolves a handle with @ and mixed case");
96	  assertThrows(() => getPersona("nobody"), "Throws on unknown persona");
97	  assertThrows(() => getPersona(""), "Throws on empty handle");
98	
99	  // Mode normalization
100	  console.log("\nTest Group: normalizeMode");
101	  assertEqual(normalizeMode("right away"), INSTANTIATION_MODES.EAGER, '"right away" -> eager');
102	  assertEqual(normalizeMode("eager"), INSTANTIATION_MODES.EAGER, '"eager" -> eager');
103	  assertEqual(normalizeMode("now"), INSTANTIATION_MODES.EAGER, '"now" -> eager');
104	  assertEqual(
105	    normalizeMode("on assignment"),
106	    INSTANTIATION_MODES.ON_ASSIGNMENT,
107	    '"on assignment" -> on_assignment'
108	  );
109	  assertEqual(
110	    normalizeMode(undefined),
111	    INSTANTIATION_MODES.ON_ASSIGNMENT,
112	    "Defaults to on_assignment"
113	  );
114	  assertThrows(() => normalizeMode("whenever"), "Throws on unknown mode");
115	
116	  // Message construction
117	  console.log("\nTest Group: buildMessages");
118	  const messages = buildMessages(getPersona("mindmappr"), "Map out a launch plan");
119	  assertEqual(messages.length, 2, "Builds a two-message array");
120	  assertEqual(messages[0].role, "system", "First message is the system prompt");
121	  assertTrue(
122	    messages[0].content.includes("MindMappr"),
123	    "System prompt carries the persona instructions"
124	  );
125	  assertEqual(messages[1], { role: "user", content: "Map out a launch plan" }, "Second message is the task");
126	
127	  // On-assignment with no task returns a deferred handle (no API call)
128	  console.log("\nTest Group: Instantiate — on assignment (deferred)");
129	  const deferred = await instantiate("oaudrey", { mode: "on assignment", silent: true });
130	  assertEqual(deferred.instantiated, false, "Deferred handle is not yet instantiated");
131	  assertEqual(deferred.mode, INSTANTIATION_MODES.ON_ASSIGNMENT, "Deferred handle reports on_assignment mode");
132	  assertTrue(typeof deferred.assign === "function", "Deferred handle exposes assign()");
133	
134	  // Fleet registration (deferred, no API calls)
135	  console.log("\nTest Group: instantiateFleet (deferred)");
136	  const fleet = await instantiateFleet(undefined, { silent: true });
137	  assertEqual(fleet.length, 4, "Fleet registers all four personas by default");
138	  assertTrue(
139	    fleet.every((f) => f.instantiated === false && typeof f.assign === "function"),
140	    "Each fleet member is a deferred handle"
141	  );
142	
143	  // Runs that would call OpenRouter should reject without a real key.
144	  // Use a fake key so the request is attempted and fails (not a missing-key short-circuit).
145	  console.log("\nTest Group: Instantiate — runs hit the router");
146	  const originalApiKey = process.env.OPENROUTER_API_KEY;
147	  process.env.OPENROUTER_API_KEY = "test-key";
148	
149	  await assertRejects(
150	    instantiate("oaudrey", { mode: "right away", silent: true }),
151	    "Eager instantiation attempts a router call (rejects with fake key)"
152	  );
153	  await assertRejects(
154	    instantiate("professor", { mode: "on assignment", task: "Research X", silent: true }),
155	    "On-assignment with a task attempts a router call (rejects with fake key)"
156	  );
157	  await assertRejects(
158	    deferred.assign("Triage the backlog", { silent: true }),
159	    "Deferred assign() attempts a router call (rejects with fake key)"
160	  );
161	  await assertRejects(
162	    instantiate("oaudrey", { mode: "on assignment", task: 123, silent: true }),
163	    "Rejects a non-string task"
164	  );
165	
166	  if (originalApiKey) {
167	    process.env.OPENROUTER_API_KEY = originalApiKey;
168	  } else {
169	    delete process.env.OPENROUTER_API_KEY;
170	  }
171	
172	  // Unknown persona rejects regardless of mode
173	  await assertRejects(
174	    instantiate("ghost", { mode: "right away", silent: true }),
175	    "Rejects unknown persona"
176	  );
177	
178	  // Summary
179	  console.log("\n" + "=".repeat(80));
180	  console.log("Test Summary");
181	  console.log("=".repeat(80));
182	  console.log(`Passed: ${testsPassed}`);
183	  console.log(`Failed: ${testsFailed}`);
184	  console.log("=".repeat(80));
185	
186	  if (testsFailed > 0) {
187	    process.exit(1);
188	  }
189	}
190	
191	if (require.main === module) {
192	  runTests().catch((err) => {
193	    console.error("Fatal test error:", err);
194	    process.exit(1);
195	  });
196	}
197	
198	module.exports = { runTests };

