1	#!/usr/bin/env node
2	// wr-lint.mjs — gate for WR/PR markdown. Catches the recurring review failures automatically.
3	// Usage: node wr-lint.mjs <file-or-glob...>   |   exit 0 clean, 1 issues found.
4	// Wire into CI / review-agent pass so these never reach a human reviewer.
5	
6	import fs from "node:fs";
7	
8	const SCAFFOLD_PATTERNS = [
9	  { re: /^#\s*Otherwise,\s*use\s+WR_TEMPLATE_BASIC\.md/im, msg: "template scaffolding comment ('Otherwise, use WR_TEMPLATE_BASIC.md') left in rendered output" },
10	  { re: /^#\s*[─—-]{10,}\s*$/m, msg: "separator-rule scaffolding line left in rendered output" }
11	];
12	
13	// Scaffolding '# WR: <owner>/<repo>' header (repo-path form) is noise ONLY when it's not the line-1 title.
14	// A legit title like "# WR: Fix duplicate return" is fine; "# WR: midnghtsapphire/revvel-standards" is scaffolding.
15	function findRepoHeaderScaffold(lines) {
16	  const out = [];
17	  lines.forEach((l, i) => {
18	    if (/^#\s*WR:\s*\S+\/\S+\s*$/i.test(l)) out.push(i + 1); // owner/repo form
19	  });
20	  return out;
21	}
22	
23	// Product-only sections that must NOT appear in a BASIC/bug-fix WR.
24	const PRODUCT_SECTIONS = [
25	  "Executive Summary", "Repository Structure", "Key Technologies",
26	  "Product/Output Selections", "Deep Web Research", "Prime Directive"
27	];
28	
29	// Title/type signals that mean BASIC template (no market research).
30	const BASIC_SIGNALS = /\b(bug|fix|style|refactor|typo|lint|unreachable|duplicate|docs?-only|chore)\b/i;
31	
32	// Unsubstituted generator tokens that must never ship.
33	const RAW_TOKENS = /\{(STARS|OPEN_ISSUES|IS_PRIVATE|IS_ARCHIVED|DESCRIPTION|REPO|LANGUAGE)\}/;
34	
35	// Bracket placeholders the full template leaves behind.
36	const BRACKET_PLACEHOLDER = /\[(Yes\/No|engine|notes|Pattern \d|Option \d|primary keyword \d|\$CPC|\$amount[^\]]*|volume|Vercel URL[^\]]*|Complaint \d|Action \d|2-3 sentence summary[^\]]*|Tree structure[^\]]*|Research findings[^\]]*|Fix|Pricing)\]/gi;
37	
38	function lintFile(path) {
39	  const text = fs.readFileSync(path, "utf8");
40	  const lines = text.split("\n");
41	  const issues = [];
42	
43	  // Track fenced code blocks so every heuristic rule below can skip them.
44	  // Without this the linter false-positives on legitimate WR content that
45	  // includes example code (e.g. `# yaml comment` lines, `{TOKEN}` examples,
46	  // `[options]` arrays, pipe tables shown as examples) — per Copilot review
47	  // on #14227 (five separate findings all reduce to the same bug).
48	  const inFence = new Array(lines.length).fill(false);
49	  let fenced = false;
50	  lines.forEach((l, i) => {
51	    if (/^```/.test(l.trim())) fenced = !fenced;
52	    inFence[i] = fenced;
53	  });
54	
55	  // 1. Exactly one H1, and it should be line 1. Skip headings inside fences.
56	  const h1Idx = lines
57	    .map((l, i) => (!inFence[i] && /^#\s+\S/.test(l) ? i : -1))
58	    .filter((i) => i >= 0);
59	  if (h1Idx.length === 0) issues.push("no H1 header found");
60	  if (h1Idx.length > 1) issues.push(`multiple H1 headers (lines ${h1Idx.map((i) => i + 1).join(", ")}) — keep one at line 1`);
61	  if (h1Idx.length && h1Idx[0] !== 0) issues.push(`H1 is at line ${h1Idx[0] + 1}, expected line 1 (scaffolding above it?)`);
62	
63	  // 2. Scaffolding patterns.
64	  for (const { re, msg } of SCAFFOLD_PATTERNS) {
65	    const m = text.match(re);
66	    if (m) {
67	      const ln = text.slice(0, m.index).split("\n").length;
68	      issues.push(`line ${ln}: ${msg}`);
69	    }
70	  }
71	  // 2b. Repo-path '# WR: owner/repo' headers (scaffolding) — flag every occurrence.
72	  for (const ln of findRepoHeaderScaffold(lines)) {
73	    issues.push(`line ${ln}: scaffolding '# WR: <owner>/<repo>' header — strip it; the title H1 is the real header`);
74	  }
75	
76	  // 3. Raw bracketed placeholders (heuristic: short ALL/Title-case tokens in brackets, not links).
77	  lines.forEach((l, i) => {
78	    if (inFence[i]) return; // skip code examples
79	    // ignore markdown links [text](url) and checkboxes [ ]/[x]
80	    const stripped = l.replace(/\[[ xX]\]/g, "").replace(/\[[^\]]+\]\([^)]+\)/g, "");
81	    const m = stripped.match(/\[[A-Za-z][^\]]{2,60}\]/);
82	    if (m) issues.push(`line ${i + 1}: raw placeholder ${m[0]} — fill it or mark "N/A — <reason>"`);
83	  });
84	
85	  // 4. Template/type mismatch: BASIC-signal title but product sections present.
86	  const isBasic = BASIC_SIGNALS.test(path) || BASIC_SIGNALS.test(lines[0] || "");
87	  if (isBasic) {
88	    for (const sec of PRODUCT_SECTIONS) {
89	      const re = new RegExp(`^#{1,4}\\s*.*${sec.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`, "im");
90	      if (re.test(text)) {
91	        issues.push(`bug/style WR contains product section "${sec}" — wrong template; use WR_TEMPLATE_BASIC.md`);
92	      }
93	    }
94	  }
95	
96	  // 5. Unsubstituted generator tokens ({STARS} etc.)
97	  const RAW_TOKENS_G = new RegExp(RAW_TOKENS.source, "g");
98	  lines.forEach((l, i) => {
99	    if (inFence[i]) return; // skip examples
100	    const m = l.match(RAW_TOKENS_G);
101	    if (m) issues.push(`line ${i + 1}: unsubstituted generator token(s) ${[...new Set(m)].join(", ")} — substitute real value or remove the row`);
102	  });
103	
104	  // 6. Full-template bracket placeholders left raw.
105	  lines.forEach((l, i) => {
106	    if (inFence[i]) return; // skip examples
107	    const m = l.match(BRACKET_PLACEHOLDER);
108	    if (m) issues.push(`line ${i + 1}: raw template placeholder ${m[0]} — fill or mark "N/A — <reason>"`);
109	  });
110	
111	  // 7. Falsely pre-checked research checklist while body has raw placeholders.
112	  const checkedItems = (text.match(/^- \[x\]/gim) || []).length;
113	  const hasRawResearch = RAW_TOKENS.test(text) || /\[(Option \d|primary keyword|\$CPC|Complaint \d|Pattern \d)\]/i.test(text);
114	  if (checkedItems >= 5 && hasRawResearch) {
115	    issues.push(`research checklist pre-marked complete (${checkedItems} [x]) but body still contains raw placeholders — false-completion signal; uncheck N/A items with a reason or fill the sections`);
116	  }
117	
118	  // 8. Issue body pasted into a metadata table cell (## heading inside a | ... | row).
119	  lines.forEach((l, i) => {
120	    if (inFence[i]) return; // skip example tables in fenced docs
121	    if (/^\|.*\|/.test(l) && /(^|\s)##\s|## Summary|## Details|## Suggested Action/.test(l)) {
122	      issues.push(`line ${i + 1}: issue body (## heading) embedded inside a table cell — breaks table rendering; move to a dedicated '## Issue Context' section`);
123	    }
124	  });
125	
126	  // 9. Title rendering artifact: stripped backtick identifier leaves a double space.
127	  if (/^#\s*WR:.*\S\s{2,}\S/.test(lines[0] || "")) {
128	    issues.push(`line 1: title has a double space — a backtick-wrapped identifier was likely stripped during generation; restore it`);
129	  }
130	
131	  return issues;
132	}
133	
134	const files = process.argv.slice(2);
135	if (!files.length) { console.error("usage: node wr-lint.mjs <files...>"); process.exit(2); }
136	let failed = 0;
137	for (const f of files) {
138	  const issues = lintFile(f);
139	  if (issues.length) {
140	    failed++;
141	    console.log(`\n✗ ${f}`);
142	    issues.forEach((i) => console.log(`   - ${i}`));
143	  } else {
144	    console.log(`✓ ${f}`);
145	  }
146	}
147	console.log(failed ? `\n${failed} file(s) with issues.` : "\nAll clean.");
148	process.exit(failed ? 1 : 0);
149

