name: Ralph Loop — Self-Healing CI
on:
  check_suite:
    types:
      - completed
permissions:
  pull-requests: write
  issues: write
  contents: read
jobs:
  ralph-trigger:
    name: Ralph Loop — Trigger Fix
    runs-on: ubuntu-latest
    # Only run on failures of check_suites whose linked PR is still OPEN.
    # check_suite.completed fires for re-runs against merged/closed PRs too;
    # without this guard, Ralph posts "Attempt N/5" comments on closed PRs
    # and tries to push fix commits to merged branches. Per strict-reviewer
    # audit finding on the agent fleet sweep.
    if: |
      github.event.check_suite.conclusion == 'failure' &&
      (github.event.check_suite.pull_requests[0] == null ||
       github.event.check_suite.pull_requests[0].state == 'open')
    steps:
      - name: Find matching open PR
        id: find-pr
        uses: actions/github-script@v9.0.0
        with:
          script: |
            const head_sha =
              context.payload.check_suite?.head_sha ||
              context.payload.workflow_run?.head_sha;

            if (!head_sha) {
              console.log('No head_sha found — skipping');
              return null;
            }

            const { data: prs } = await github.rest.pulls.list({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
            });

            const pr = prs.find(p => p.head.sha === head_sha);
            if (!pr) {
              console.log(`No open PR found for sha: ${head_sha}`);
              return null;
            }

            console.log(`Found PR #${pr.number}: ${pr.title}`);
            return pr.number;
      - name: Count existing Ralph Loop attempts
        id: count-attempts
        if: steps.find-pr.outputs.result != 'null'
        uses: actions/github-script@v9.0.0
        with:
          script: |
            const pr_number = parseInt('${{ steps.find-pr.outputs.result }}');
            let comments = []; try { const { data } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr_number,
              per_page: 100,
            }); comments = data; } catch (e) { console.log(`⚠️ error getting comments: ${e.message}`); }
            const count = comments.filter(c =>
              c.body.includes('🔄 **Ralph Loop**')
            ).length;
            console.log(`Ralph Loop has fired ${count} time(s) on PR #${pr_number}`);
            return count;
      - name: Post Ralph Loop fix request
        if: |
          steps.find-pr.outputs.result != 'null' &&
          fromJSON(steps.count-attempts.outputs.result) < 5
        uses: actions/github-script@v9.0.0
        with:
          script: |
            const pr_number = parseInt('${{ steps.find-pr.outputs.result }}');
            const attempt   = parseInt('${{ steps.count-attempts.outputs.result }}') + 1;
            const workflow  =
              context.payload.check_suite?.app?.name ||
              context.payload.workflow_run?.name ||
              'CI';
            const conclusion =
              context.payload.check_suite?.conclusion ||
              context.payload.workflow_run?.conclusion ||
              'failure';

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr_number,
              body:
                `🔄 **Ralph Loop** — Attempt ${attempt}/5\n\n` +
                `The \`${workflow}\` check finished with status: \`${conclusion}\`.\n\n` +
                `OpenRouter triage (\`openrouter-triage.yml\`) will pick this up and:\n` +
                `1. Read the CI failure output\n` +
                `2. Identify the root cause\n` +
                `3. Make the **minimum** change required to fix it\n` +
                `4. Push a single commit: \`fix: [description] (ralph-loop attempt ${attempt})\`\n\n` +
                `> ⛔ This PR is blocked from merging until all CI checks pass.`,
            });

            // Add blocking labels
            const labels = ['won\'t-merge', 'auto-fix', 'copilot'];
            for (const label of labels) {
              try {
                await github.rest.issues.addLabels({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: pr_number,
                  labels: [label],
                });
              } catch (err) {
                // Label may not exist in this repo — skip
                console.log(`Could not add label "${label}": ${err.message}`);
              }
            }

            // Routing is handled by .github/workflows/openrouter-triage.yml
            // via OpenRouter API (see docs/OPENROUTER_TRIAGE_PROCESS.md); do
            // not assign @Copilot / copilot-swe-agent here.
      - name: Escalate to human (max retries exceeded)
        if: |
          steps.find-pr.outputs.result != 'null' &&
          fromJSON(steps.count-attempts.outputs.result) >= 5
        uses: actions/github-script@v9.0.0
        with:
          script: |
            const pr_number = parseInt('${{ steps.find-pr.outputs.result }}');

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr_number,
              body:
                `⚠️ **Ralph Loop — Escalation Required**\n\n` +
                `This PR has failed **5 consecutive** auto-fix attempts. ` +
                `Automated recovery has been exhausted.\n\n` +
                `@midnghtsapphire Please review this PR manually.`,
            });

            // Swap labels to human-review state
            for (const label of ['won\'t-merge', 'auto-fix']) {
              try {
                await github.rest.issues.removeLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: pr_number,
                  name: label,
                });
              } catch (_) {}
            }
            try {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr_number,
                labels: ['needs-human', 'blocked'],
              });
            } catch (err) {
              console.log(`Could not add escalation labels: ${err.message}`);
            }
    timeout-minutes: 30
  ralph-unblock:
    name: Ralph Loop — Unblock on Pass
    runs-on: ubuntu-latest
    if: |
      github.event.check_suite.conclusion == 'success' ||
      github.event.workflow_run.conclusion == 'success'
    steps:
      - name: Find matching open PR
        id: find-pr
        uses: actions/github-script@v9.0.0
        with:
          script: |
            const head_sha =
              context.payload.check_suite?.head_sha ||
              context.payload.workflow_run?.head_sha;

            if (!head_sha) return null;

            const { data: prs } = await github.rest.pulls.list({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
            });

            const pr = prs.find(p => p.head.sha === head_sha);
            return pr?.number ?? null;
      - name: Remove won't-merge label on CI pass
        if: steps.find-pr.outputs.result != 'null'
        uses: actions/github-script@v9.0.0
        with:
          script: |
            const pr_number = parseInt('${{ steps.find-pr.outputs.result }}');

            // Fetch current labels
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: pr_number,
            });

            const labelNames = pr.labels.map(l => l.name);

            // Only act if the Ralph Loop was managing this PR
            if (!labelNames.includes('auto-fix') && !labelNames.includes("won't-merge")) {
              console.log('PR has no Ralph Loop labels — skipping');
              return;
            }

            // Remove blocking labels
            for (const label of ["won't-merge", 'auto-fix']) {
              try {
                await github.rest.issues.removeLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: pr_number,
                  name: label,
                });
              } catch (_) {}
            }

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr_number,
              body: `✅ **Ralph Loop — All checks passed!**\n\nMerge block removed. This PR is ready to merge.`,
            });
    timeout-minutes: 30
