39	            ]);
40	            const ALLOWED_CONCLUSIONS = new Set(['success', 'skipped', 'neutral']);
41	
42	            // Poll until all external checks complete or we time out.
43	            const INITIAL_WAIT_MS  = 15_000;   // 15 s — let checks register first
44	            const POLL_INTERVAL_MS = 30_000;   // re-check every 30 s
45	            const MAX_WAIT_MS      = 8 * 60 * 1000; // 8 minutes — give up after this
46	
47	            await new Promise(r => setTimeout(r, INITIAL_WAIT_MS));
48	
49	            let elapsed = INITIAL_WAIT_MS;
50	
51	            while (true) {
52	              const { data } = await github.rest.checks.listForRef({
53	                owner: context.repo.owner,
54	                repo: context.repo.repo,
55	                ref: context.payload.pull_request.head.sha,
56	                per_page: 100,
57	              });
58	
59	              const runs = data.check_runs.filter(r => !SELF_JOB_NAMES.has(r.name));
60	              core.info(`[${elapsed / 1000}s] Found ${runs.length} external check run(s):`);
61	              runs.forEach(r => core.info(`  • ${r.name}: ${r.status} / ${r.conclusion}`));
62	
63	              if (runs.length === 0) {
64	                // No external CI configured — safe to promote immediately.
65	                core.info('No external check runs found — auto-promoting.');
66	                core.setOutput('all_passed', 'true');
67	                return true;
68	              }
69	
70	              const allDone = runs.every(r => r.status === 'completed');
71	
72	              if (allDone) {
73	                const allPassed = runs.every(r => ALLOWED_CONCLUSIONS.has(r.conclusion));
74	                if (!allPassed) {
75	                  const failed = runs.filter(r => !ALLOWED_CONCLUSIONS.has(r.conclusion));
