+// ── Runner ──────────────────────────────────────────────────────────────────
+
+function runAll() {
+  return CHECKS.map(c => {
+    let r;
+    try { r = c.run(); } catch (e) { r = { pass: false, detail: `Check errored: ${e.message}` }; }
