+      lines.push('');
+    }
+    for (const f of informational) {
+      lines.push(`#### ${f.name}`);
+      lines.push('');
+      lines.push('```');
+      lines.push(f.detail);
+      lines.push('```');
+      lines.push('');
+    }
+  }
